#!/usr/bin/env python3
import sys, os, re, gzip, json, datetime as dt
from decimal import Decimal, ROUND_HALF_UP
import xml.etree.ElementTree as ET

FACT = {'kg': Decimal(1), 'g': Decimal('0.001'), 'lb': Decimal('0.45392'), 'oz': Decimal('0.02837')}
ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
UNITS = set(FACT)
COUNTED = {'delivered', 'delivered_late'}


def load(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be')
    m = re.search(rb'^#[ \t]*charset[ \t]*:[ \t]*([\w.:-]+)', b[:4000], re.M | re.I)
    enc = m.group(1).decode() if m else 'utf-8'
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode('latin-1')


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def parse_id(s):
    m = re.match(r'^\s*SH\W*0*(\d+)\s*$', s or '', re.I)
    return int(m.group(1)) if m else None


def parse_num(s, dec):
    s = s.strip()
    if dec == ',':
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


def parse_weight(raw, dec, unit):
    raw = raw.strip()
    m = re.match(r'^([-+0-9.,]+)\s*([A-Za-z]+)$', raw)
    if m and m.group(2).lower() in UNITS:
        raw, unit = m.group(1), m.group(2).lower()
    return parse_num(raw, dec) * FACT[unit]


MONTHS = {m: i + 1 for i, m in enumerate('jan feb mar apr may jun jul aug sep oct nov dec'.split())}


def parse_date(s, form):
    """returns datetime.date (UTC)"""
    s = s.strip()
    m = re.match(r'^(\d{4})-(\d\d)-(\d\d)(?:[T ](\d\d):(\d\d)(?::(\d\d)(\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d)?)?$', s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        if m.group(4) is None:
            return dt.date(y, mo, d)
        t = dt.datetime(y, mo, d, int(m.group(4)), int(m.group(5)), int(m.group(6) or 0))
        off = m.group(8)
        if off and off != 'Z':
            sign = 1 if off[0] == '+' else -1
            digits = off[1:].replace(':', '')
            t -= sign * dt.timedelta(hours=int(digits[:2]), minutes=int(digits[2:]))
        return t.date()
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?,?\s+(\d{4})$', s)
    if m:
        return dt.date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    form = (form or 'iso').strip()
    f = form.lower()
    if f == 'serial':
        return dt.date(1899, 12, 30) + dt.timedelta(days=int(float(s)))
    p = re.split(r'[-/.]', s)
    if len(p) == 3:
        a, b, c = [int(x) for x in p]
        if f in ('dmy', 'dd/mm/yyyy', 'dd.mm.yyyy', 'dd-mm-yyyy'):
            return dt.date(c, b, a)
        if f in ('mm/dd/yyyy', 'mdy'):
            return dt.date(c, a, b)
        if f in ('iso', 'ymd', 'yyyy-mm-dd'):
            return dt.date(a, b, c)
    if re.match(r'^\d{8}$', s):
        return dt.date(int(s[:4]), int(s[4:6]), int(s[6:]))
    if re.match(r'^\d{7}$', s):
        return dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:]) - 1)
    raise ValueError('bad date %r' % s)


def rec(num, typ, status, weight, date):
    return {'num': num, 'type': typ, 'status': status, 'kg': weight, 'date': date}


# ---------- delimited ----------
DELIMS = {'east': ',', 'lakeside': ',', 'river': '\t', 'west': ';', 'harbor': '|'}
COLS = {
    'east': {'id', 'type', 'shipped', 'gross', 'net', 'status', 'note'},
    'lakeside': {'id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'},
    'river': {'t', 'ref', 'shipped', 'weight', 'status'},
    'west': {'id', 'typ', 'shipped', 'weight', 'status', 'note'},
    'harbor': {'rec', 'ref', 'date', 'weight', 'state'},
}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY', 'harbor': 'iso'}
TYPEMAP = {'n': 'new', 'new': 'new', '': 'new', 'c': 'correction', 'cor': 'correction', 'corr': 'correction',
           'correction': 'correction', 'amend': 'correction', 'v': 'void', 'void': 'void'}
WEIGHT_RE = re.compile(r'^(gross|weight)(?:_(kg|g|lb|oz))?$')


def logical_lines(text, quoting):
    lines = text.replace('\r\n', '\n').replace('\r', '\n').split('\n')
    i = 0
    while i < len(lines):
        l = lines[i]
        i += 1
        if l.startswith('#') or not l.strip():
            yield l
            continue
        if quoting:
            while l.count('"') % 2 == 1 and i < len(lines):
                l += '\n' + lines[i]
                i += 1
        yield l


def split_csv(l):
    out, cur, inq, i = [], [], False, 0
    while i < len(l):
        c = l[i]
        if inq:
            if c == '"':
                if i + 1 < len(l) and l[i + 1] == '"':
                    cur.append('"')
                    i += 1
                else:
                    inq = False
            else:
                cur.append(c)
        elif c == '"':
            inq = True
        elif c == ',':
            out.append(''.join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    out.append(''.join(cur))
    return out


def parse_delimited(depot, text):
    delim = DELIMS[depot]
    quoting = delim == ','
    cols = COLS[depot]
    seq = None
    dirs = {}
    header = None
    recs = []
    for l in logical_lines(text, quoting):
        if not l.strip():
            continue
        if l.startswith('#'):
            m = re.match(r'^#\s*([A-Za-z][A-Za-z ]*?)\s*:\s*(.*?)\s*$', l)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).lower())
                dirs[name] = m.group(2)
                if name == 'seq' and seq is None:
                    seq = int(m.group(2))
            else:
                m = re.search(r'\bseq\s*=\s*(\d+)', l)
                if m and seq is None:
                    seq = int(m.group(1))
            continue
        row = split_csv(l) if quoting else l.split(delim)
        names = [x.strip().lower() for x in row]
        if all(n in cols or WEIGHT_RE.match(n) for n in names) and 'id' in names + ['ref'] or \
                (all(n in cols or WEIGHT_RE.match(n) for n in names) and len(set(names) & {'id', 'ref', 'rec', 't'}) > 0):
            header = names
            continue
        if header is None:
            continue
        row_unit = None
        if len(row) == len(header) + 1:
            wi = next((i for i, n in enumerate(header) if WEIGHT_RE.match(n) and n not in ('net',)), None)
            idx = None
            if wi is not None and wi + 1 < len(row) and row[wi + 1].strip().lower() in UNITS:
                idx = wi + 1
            else:
                for i, v in enumerate(row):
                    if i > 0 and v.strip().lower() in UNITS:
                        idx = i
                        break
            if idx is not None:
                row_unit = row[idx].strip().lower()
                row = row[:idx] + row[idx + 1:]
        row = row + [''] * (len(header) - len(row))
        d = dict(zip(header, row))
        idv = d.get('id', d.get('ref', ''))
        num = parse_id(idv)
        if num is None:
            continue
        tv = d.get('type', d.get('kind', d.get('t', d.get('typ', d.get('rec', ''))))).strip().lower()
        typ = TYPEMAP.get(tv)
        if typ is None:
            continue
        if typ == 'void':
            recs.append(rec(num, 'void', None, None, None))
            continue
        # weight
        wcol = next((n for n in header if WEIGHT_RE.match(n) and n != 'net'), None)
        unit = 'kg'
        base = {'west': 'kg'}.get(depot, 'kg')
        unit = base
        for k in ('weight unit', 'unit'):
            if k in dirs:
                u = dirs[k].split()[0].lower() if dirs[k].split() else ''
                if u in UNITS:
                    unit = u
        if row_unit:
            unit = row_unit
        mm = WEIGHT_RE.match(wcol)
        if mm.group(2):
            unit = mm.group(2)
        dec = ',' if depot == 'west' or (depot != 'west' and '(decimal comma)' in dirs.get('weight unit', '')) else '.'
        kg = parse_weight(d[wcol], dec, unit)
        form = dirs.get('dates', dirs.get('date format', BASE_DATE[depot]))
        dcol = 'date' if 'date' in d else 'shipped'
        date = parse_date(d[dcol], form)
        st = d.get('status', d.get('state', ''))
        if depot == 'harbor':
            st = {'DLV': 'delivered', 'DLL': 'delivered_late', 'CAN': 'cancelled', 'RET': 'returned',
                  'HLD': 'held'}.get(st.strip().upper(), st)
        recs.append(rec(num, typ, norm_status(st), kg, date))
    return seq, recs


# ---------- fixed width ----------
LAYOUTS = {
    'FW1': dict(len=42, id=(0, 9), type=(9, 10), date=(10, 17), w=(17, 25), st=(25, 26), df='doy', wu='g', div=1),
    'FW2': dict(len=43, type=(0, 1), id=(1, 10), date=(10, 18), w=(18, 26), st=(26, 27), df='ymd', wu='kg', div=100),
    'FW3': dict(len=41, id=(0, 9), date=(9, 16), type=(16, 17), w=(17, 24), st=(24, 25), df='doy', wu='lb', div=10),
}
FWST = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def parse_fixed(text):
    seq = None
    cur = None
    recs = []
    bylen = {v['len']: k for k, v in LAYOUTS.items()}
    for l in text.replace('\r\n', '\n').split('\n'):
        if l.startswith('\x0c') or not l.strip():
            continue
        if l.startswith('#'):
            m = re.match(r'^#LAYOUT\s+(\w+)', l)
            if m:
                cur = m.group(1).upper()
            m = re.match(r'^#SEQ\s+(\d+)', l)
            if m and seq is None:
                seq = int(m.group(1))
            continue
        if re.match(r'^\s*SOUTH DEPOT', l):
            continue
        name = bylen.get(len(l))
        if name is None:
            if cur in LAYOUTS and len(l) < LAYOUTS[cur]['len']:
                l = l.ljust(LAYOUTS[cur]['len'])
                name = cur
            else:
                continue
        L = LAYOUTS[name]
        f = lambda k: l[L[k][0]:L[k][1]]
        num = parse_id(f('id'))
        if num is None:
            continue
        typ = TYPEMAP.get(f('type').strip().lower())
        if typ is None:
            continue
        if typ == 'void':
            recs.append(rec(num, 'void', None, None, None))
            continue
        ds = f('date')
        if L['df'] == 'doy':
            date = dt.date(int(ds[:4]), 1, 1) + dt.timedelta(days=int(ds[4:]) - 1)
        else:
            date = dt.date(int(ds[:4]), int(ds[4:6]), int(ds[6:8]))
        kg = Decimal(int(f('w'))) / L['div'] * FACT[L['wu']]
        recs.append(rec(num, typ, FWST.get(f('st').strip().upper(), 'unknown'), kg, date))
    return seq, recs


# ---------- XML ----------
def parse_xml(text):
    text = re.sub(r'^\s*<\?xml[^>]*\?>', '', text)
    root = ET.fromstring(text)
    seq = int(root.get('seq')) if root.get('seq') else None
    runit = (root.get('weight-unit') or 'kg').lower()
    recs = []
    for sh in root.iter('shipment'):
        def get(name):
            v = sh.get(name)
            if v is not None:
                return v
            c = sh.find(name)
            return c.text if c is not None and c.text is not None else None
        num = parse_id(sh.get('id') or get('id'))
        if num is None:
            continue
        typ = TYPEMAP.get((sh.get('type') or 'new').strip().lower())
        if typ == 'void':
            recs.append(rec(num, 'void', None, None, None))
            continue
        w = sh.find('weight')
        unit = (w.get('unit') if w is not None and w.get('unit') else sh.get('weight-unit') or runit).lower()
        wt = w.text if w is not None else sh.get('weight')
        kg = parse_weight(wt, '.', unit)
        date = parse_date(get('shipped'), 'iso')
        recs.append(rec(num, typ, norm_status(get('status')), kg, date))
    return seq, recs


# ---------- JSONL ----------
def parse_jsonl(text):
    seq = None
    recs = []
    for l in text.split('\n'):
        l = l.strip()
        if not l:
            continue
        v = json.loads(l)
        objs = v if isinstance(v, list) else [v]
        for o in objs:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and 'id' not in o:
                if seq is None and 'seq' in o['meta']:
                    seq = int(o['meta']['seq'])
                continue
            num = parse_id(str(o.get('id', '')))
            if num is None:
                continue
            typ = TYPEMAP.get(str(o.get('kind', 'new')).lower())
            if typ == 'void':
                recs.append(rec(num, 'void', None, None, None))
                continue
            kg = None
            for k, val in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', k)
                if m:
                    kg = parse_weight(str(val), '.', m.group(1))
            date = parse_date(o['shipped_at'], 'iso')
            recs.append(rec(num, typ, norm_status(o.get('status')), kg, date))
    return seq, recs


def parse_file(path, depot):
    text = load(path)
    if text.startswith('\ufeff'):
        text = text[1:]
    s = text.lstrip()
    if depot in DELIMS:
        return parse_delimited(depot, text)
    if depot == 'south':
        return parse_fixed(text)
    if depot == 'central':
        return parse_xml(text)
    if depot == 'north':
        return parse_jsonl(text)
    # unknown depot: sniff
    if s.startswith('<'):
        return parse_xml(text)
    if s.startswith('{') or s.startswith('['):
        return parse_jsonl(text)
    raise ValueError('unknown depot ' + depot)


def main(data_dir, out_file):
    files = {}
    for fn in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, fn)
        if os.path.isfile(p):
            files.setdefault(fn.split('-')[0], []).append(p)
    cur = {}
    corrections = resends = 0
    for depot, paths in files.items():
        parsed = []
        for i, p in enumerate(paths):
            seq, recs = parse_file(p, depot)
            parsed.append((seq if seq is not None else -1, i, recs))
        parsed.sort(key=lambda x: (x[0], x[1]))
        c = {}
        for _, _, recs in parsed:
            for r in recs:
                if r['type'] == 'new':
                    if r['num'] in c:
                        resends += 1
                    else:
                        c[r['num']] = r
                elif r['type'] == 'correction':
                    c[r['num']] = r
                    corrections += 1
                else:
                    c.pop(r['num'], None)
                    corrections += 1
        cur[depot] = c
    rank = {d: i for i, d in enumerate(ORDER)}
    depots_sorted = sorted(cur, key=lambda d: (rank.get(d, 99), d))
    owner = {}
    handovers = 0
    seen_multi = set()
    for d in depots_sorted:
        for n, r in cur[d].items():
            if n in owner:
                seen_multi.add(n)
            else:
                owner[n] = (d, r)
    handovers = len(seen_multi)
    dep = {d: [0, Decimal(0)] for d in files}
    months = {}
    for n, (d, r) in owner.items():
        if r['status'] in COUNTED:
            dep[d][0] += 1
            dep[d][1] += r['kg']
            k = '%04d-%02d' % (r['date'].year, r['date'].month)
            m = months.setdefault(k, [0, Decimal(0)])
            m[0] += 1
            m[1] += r['kg']
    q = lambda x: float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
    out = {
        'depots': {d: {'shipments': dep[d][0], 'total_kg': q(dep[d][1])} for d in sorted(dep)},
        'months': {k: {'shipments': months[k][0], 'total_kg': q(months[k][1])} for k in sorted(months)},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': handovers,
    }
    with open(out_file, 'w') as f:
        json.dump(out, f, indent=2)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
